--- index.html
+++ index.html
@@ -82,9 +82,9 @@
 function renderInfo(){const c=byId(selected);if(!c)return;document.getElementById('countryFlag').textContent=c.flag;document.getElementById('countryName').textContent=c.name;document.getElementById('countryMeta').textContent=`${c.region} · ${c.owner==='ally'?'Friendly territory':c.owner==='axis'?'Axis-controlled':'Neutral territory'}`;const ob=document.getElementById('ownerBadge');ob.textContent=c.owner==='ally'?'ALLIED':c.owner==='axis'?'AXIS':'NEUTRAL';ob.style.color=color(c.owner);ob.style.borderColor=color(c.owner)+'77';document.getElementById('armyCount').textContent=c.army;document.getElementById('industryCount').textContent=c.industry;document.getElementById('statusCount').textContent=c.army>=4?'READY':'ACTIVE';document.getElementById('supplyTop').textContent=supply;document.getElementById('turnLabel').textContent=`TURN ${String(turn).padStart(2,'0')} · ${gameOver?'CAMPAIGN OVER':'YOUR MOVE'}`;document.getElementById('ordersRemain').textContent=`${orders} ORDER${orders===1?'':'S'}`;document.getElementById('moveMode').classList.toggle('active',mode==='move');document.getElementById('attackMode').classList.toggle('active',mode==='attack');const own=c.owner==='ally';document.getElementById('moveMode').disabled=!own||orders<1;document.getElementById('attackMode').disabled=!own||orders<1;let msg=own?`Choose a friendly territory, then click a <em>neighbor</em> to ${mode}.`:`Select one of your friendly territories to issue orders.`;if(mode==='attack'&&supply<1)msg='Not enough supply to attack. End your turn to resupply.';document.getElementById('orderHint').innerHTML=msg;document.getElementById('intel').innerHTML=own?`<strong>${c.name}</strong> is under Allied control. ${c.adj.length} neighboring territories within reach. ${c.owner==='ally'?'You can move forces or launch an attack.':''}`:`<strong>${c.name}</strong> is ${c.owner==='axis'?'an Axis stronghold':'currently neutral'}. ${c.army} defending armies · ${c.industry} industry. Select an Allied territory to issue orders.`;}
 function notify(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
 function log(text){const box=document.getElementById('events'),e=document.createElement('div');e.className='event';e.innerHTML=`<time>T${String(turn).padStart(2,'0')}</time><span>${text}</span>`;box.prepend(e);while(box.children.length>5)box.lastElementChild.remove()}
 function clickCountry(c){if(gameOver)return;const sel=byId(selected);if(c.id===selected){renderInfo();return}if(sel.owner==='ally'&&sel.adj.includes(c.id)&&orders>0){if(mode==='move'){if(c.owner!=='ally'){notify('Movement orders require friendly territory.');selected=c.id;renderInfo();draw();return}if(sel.army<=1){notify('At least one army must remain behind.');return}sel.army--;c.army++;orders--;log(`Army moved from <b>${sel.name}</b> to <b>${c.name}</b>.`);notify(`Reinforcements arrived in ${c.name}.`)}else{if(supply<1){notify('Not enough supply. End your turn to resupply.');return}if(c.owner==='ally'){notify('That territory is already Allied. Switch to Move.');selected=c.id;renderInfo();draw();return}attack(sel,c)}selected=c.id;renderInfo();draw();return}selected=c.id;renderInfo();draw();}
-function attack(from,to){supply--;orders--;let atk=from.army-1;if(atk<1){notify('Not enough armies to attack.');return}const atkRoll=Math.random()*atk+atk*.55,defRoll=Math.random()*to.army+to.army*.58;log(`Allied forces ${atk>to.army?'strike':'engage'} at <b>${to.name}</b>!`);if(atkRoll>defRoll){const loss=Math.max(1,Math.floor(to.army*.55));to.army=Math.max(1,to.army-loss);to.owner='ally';to.army=Math.max(1,Math.floor(atk*.55));from.army=Math.max(1,from.army-Math.max(1,Math.ceil(atk*.4)));log(`<b>${to.name}</b> captured! The front advances.`);notify(`Victory! ${to.name} is now Allied.`);if(to.owner==='ally'&&countries.filter(c=>c.owner==='axis').length===0){finish(true)}}else{from.army=Math.max(1,from.army-Math.max(1,Math.ceil(atk*.5)));to.army=Math.max(1,to.army-Math.max(1,Math.floor(to.army*.25)));log(`Attack on <b>${to.name}</b> repelled. Our forces regroup.`);notify('Attack repelled. Rally your forces.')}}
+function attack(from,to){let atk=from.army-1;if(atk<1){notify('Not enough armies to attack.');return}supply--;orders--;const atkRoll=Math.random()*atk+atk*.55,defRoll=Math.random()*to.army+to.army*.58;log(`Allied forces ${atk>to.army?'strike':'engage'} at <b>${to.name}</b>!`);if(atkRoll>defRoll){const loss=Math.max(1,Math.floor(to.army*.55));to.army=Math.max(1,to.army-loss);to.owner='ally';to.army=Math.max(1,Math.floor(atk*.55));from.army=Math.max(1,from.army-Math.max(1,Math.ceil(atk*.4)));log(`<b>${to.name}</b> captured! The front advances.`);notify(`Victory! ${to.name} is now Allied.`);if(to.owner==='ally'&&countries.filter(c=>c.owner==='axis').length===0){finish(true)}}else{from.army=Math.max(1,from.army-Math.max(1,Math.ceil(atk*.5)));to.army=Math.max(1,to.army-Math.max(1,Math.floor(to.army*.25)));log(`Attack on <b>${to.name}</b> repelled. Our forces regroup.`);notify('Attack repelled. Rally your forces.')}}
 function finish(win){gameOver=true;setTimeout(()=>{document.querySelector('#intro .modal').innerHTML=`<div class="modal-kicker">CAMPAIGN COMPLETE</div><h1>${win?'Victory is yours.':'The front has fallen.'}</h1><p>${win?'The Allied coalition controls the world. You have secured a place in history.':'Our forces have lost their last foothold. The world awaits another commander.'}</p><button class="start-btn" onclick="location.reload()">PLAY AGAIN &nbsp; →</button>`;document.getElementById('intro').style.display='grid'},400)}
 function enemyTurn(){turn++;supply=Math.min(20,supply+2);orders=2;const axis=countries.filter(c=>c.owner==='axis');axis.forEach(c=>{c.army=Math.min(8,c.army+(Math.random()<.65?1:0));const targets=c.adj.map(byId).filter(t=>t.owner==='ally'&&c.army>=4);if(targets.length&&Math.random()<.38){const t=targets[Math.floor(Math.random()*targets.length)];const power=c.army-1;if(Math.random()*power>Math.random()*t.army*1.35){t.army=Math.max(1,t.army-1);if(t.army===1&&Math.random()<.15){t.owner='axis';t.army=2;log(`Axis forces seize <b>${t.name}</b>!`)}}else c.army=Math.max(1,c.army-1)}});countries.filter(c=>c.owner==='ally').forEach(c=>{if(c.industry>=3&&Math.random()<.3)c.army=Math.min(8,c.army+1)});const allied=countries.filter(c=>c.owner==='ally');if(!allied.length){finish(false);return}selected=allied[0].id;renderInfo();draw();notify(`Turn ${turn}: Supplies replenished. The enemy has moved.`);}
 function hit(e){const rect=canvas.getBoundingClientRect(),g=geometry(),x=e.clientX-rect.left,y=e.clientY-rect.top;let best=null,dist=Infinity;countries.forEach(c=>{const [cx,cy]=project(c.x,c.y,g),d=Math.hypot(cx-x,cy-y);if(d<dist){dist=d;best=c}});if(dist<36*zoom)clickCountry(best)}
 canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y,moved:false};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag&&e.buttons){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(drag.moved){pan.x=drag.px+dx;pan.y=drag.py+dy;draw()}}});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved)hit(e);drag=null});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.8,Math.min(2.2,zoom+(e.deltaY<0?.1:-.1)));draw()},{passive:false});
